) A -- START WITH A.parent_idx = 0 -- CONNECT BY PRIOR A.board_idx = A.parent_idx
-- ORDER SIBLINGS BY A.add_date DESC ORDER BY A.add_date DESC
A.add_date DESC, A.board_idx DESC
${pagingBottom} ) CMS_BOARD_T

SELECT CMS_BOARD_T.*, TRUNC(TO_CHAR(SYSDATE,'yyyyMMdd')) - TRUNC(TO_CHAR(add_date,'yyyyMMdd')) AS date_gap, ( SELECT COUNT(*) FROM CMS_BOARD_COMMENT a WHERE a.board_idx = CMS_BOARD_T.board_idx AND a.delete_yn = 'N' ) AS comment_count, getCodeIdToCodeName(#{homepage_id},#{category1Manage},category1) as category1_name, getCodeIdToCodeName(#{homepage_id},#{category2Manage},category2) as category2_name, getCodeIdToCodeName(#{homepage_id},#{category3Manage},category3) as category3_name, getCodeIdToCodeName(#{homepage_id},#{category4Manage},category4) as category4_name, getCodeIdToCodeName(#{homepage_id},#{category5Manage},category5) as category5_name, getCodeIdToCodeName('CMS',#{request_code},request_state) as request_state_str FROM ( ${pagingTop} SELECT A.* FROM ( SELECT manage_idx, board_idx, group_idx, parent_idx, group_depth, view_count, notice_yn, title, add_id, content, user_name, user_ip, delete_yn, add_date, modify_date, file_count, preview_img, secret_yn, content_summary, category1, category2, category3, category4, category5,request_state
