SELECT
	(select menu_idx from cms_menu
	where manage_idx = a.manage_idx
	and menu_type = 'BOARD') as menu_idx, a.*
FROM (
	SELECT
		*
	FROM
		CMS_BOARD
	WHERE
		imsi_v_1 IS NOT NULL
	AND imsi_v_1 = #{imsi_v_1}
	AND delete_yn = 'N'

	AND imsi_v_2 = #{imsi_v_2}

	AND manage_idx = (
						SELECT manage_idx FROM CMS_BOARD_MANAGE
						WHERE board_type = 'MOVIE'
						AND homepage_id = #{homepage_id}
						)

	AND category5 = #{category5}


		AND category1 = #{category1}

	) a
	ORDER BY imsi_v_2;

